#!/usr/bin/env node
/**
 * @file check-release-artifacts.mjs
 * @brief Release artifact validator for the npm tarball generated by `scripts/build.sh` (PKG-075..PKG-079).
 * @details Validates `dist/<name>-<version>.tgz` and the repository `dist/` tree offline, in this
 *          order: (1) tarball listing against the npm-invariant plus runtime-prefix allowlist and the
 *          required entry set (PKG-075); (2) extraction into a private temp directory, then the packed
 *          `package/package.json` name and version against the repository `package.json` (PKG-076);
 *          (3) every `bin`, `main`, and `exports` target present in the tarball (PKG-076); (4) every
 *          skill `path` and `debug` entry of the packed `src/resources/skills/manifest.json` present
 *          (PKG-077); (5) byte equality between every packed `dist/` file and the repository `dist/`
 *          tree, in both directions so stale or missing files are reported (PKG-078); (6) `node --check`
 *          on the packed `dist/cli.js` and `dist/index.js` (PKG-079); (7) execution of the repository
 *          `dist/cli.js --help` with exit 0 and `mcp-google-api` on stdout (PKG-079). Every failed check
 *          is collected and reported; the process exits 1 when any check fails.
 *          Complexity: O(E + F) where E is the tarball entry count and F the packed file byte total.
 * @satisfies PKG-075, PKG-076, PKG-077, PKG-078, PKG-079
 * @note Writes only under the OS temp directory (extraction, removed in `finally`). No network access,
 *       no dependency installation, no publication. stdout carries per-check `ok:` lines; stderr carries
 *       `FAILED:` diagnostics.
 * @pre `dist/<name>-<version>.tgz` exists (produced by `scripts/build.sh`); `dist/cli.js` exists.
 * @post No repository file is modified; the temp extraction directory is removed.
 */
import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, posix, relative } from "node:path";
import { fileURLToPath } from "node:url";

/** Repository root resolved from this script location (cwd-independent). */
const PROJECT_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Directory name npm uses as the root of every packed tarball entry. */
const PACKAGE_ROOT_DIR = "package";

/** Upper bound for captured `tar` stdout in bytes (dist sourcemaps are below this). */
const TAR_MAX_BUFFER_BYTES = 64 * 1024 * 1024;

/** Timeout in milliseconds for the packaged CLI smoke run. */
const CLI_SMOKE_TIMEOUT_MS = 60000;

/** npm-invariant files always packed regardless of the `files` allowlist (PKG-038). */
const INVARIANT_FILES = new Set(["package.json", "README.md", "CHANGELOG.md", "LICENSE", "LICENSE.md", "LICENSE.txt"]);

/** Runtime directory prefixes permitted in the packed tarball (PKG-038); docs/ is non-runtime and excluded. */
const ALLOWED_PREFIXES = ["bin/", "dist/", "src/resources/skills/"];

/** Entries that MUST exist in the packed tarball (PKG-075). */
const REQUIRED_ENTRIES = [
  "package.json",
  "README.md",
  "CHANGELOG.md",
  "bin/mcp-google-api.mjs",
  "dist/cli.js",
  "dist/index.js",
  "dist/cli.d.ts",
  "dist/index.d.ts",
  "src/resources/skills/manifest.json",
];

/** Packed entries whose syntax is verified with `node --check` (PKG-079). */
const SYNTAX_CHECKED_ENTRIES = ["dist/cli.js", "dist/index.js"];

/** Accumulated failure diagnostics; a non-empty list makes the process exit 1. */
const failures = [];

/**
 * @brief Records one failed check diagnostic.
 * @details Appends to the module-level `failures` list; no I/O. Complexity O(1).
 * @param message {string} Human-readable failure description naming the failed check.
 * @return {void}
 * @side_effect Mutates `failures`.
 */
function recordFailure(message) {
  failures.push(message);
}

/**
 * @brief Prints one passing-check line on stdout.
 * @details Complexity O(1).
 * @param message {string} Description of the satisfied check.
 * @return {void}
 * @side_effect Writes to stdout.
 */
function recordOk(message) {
  console.log(`[check-release-artifacts] ok: ${message}`);
}

/**
 * @brief Runs `tar` synchronously and returns its captured stdout.
 * @details Uses buffer encoding so binary member content is preserved. Throws on spawn error
 * or non-zero status, including the captured stderr text. Complexity O(output size).
 * @param args {string[]} Arguments forwarded verbatim to `tar`.
 * @return {Buffer} Captured stdout bytes.
 * @throws {Error} When `tar` cannot be spawned or exits non-zero.
 */
function runTar(args) {
  const result = spawnSync("tar", args, { maxBuffer: TAR_MAX_BUFFER_BYTES });
  if (result.error) {
    throw new Error(`tar could not be spawned: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(`tar ${args.join(" ")} failed: ${result.stderr.toString("utf8").trim()}`);
  }
  return result.stdout;
}

/**
 * @brief Lists the file entries of a tarball with the `package/` root prefix stripped.
 * @details Directory entries (trailing `/`) are skipped. Every entry MUST begin with
 * `package/`; any other root is a structural failure. Complexity O(E).
 * @param tarballPath {string} Absolute path to the `.tgz` file.
 * @return {string[]} Relative file paths in tarball order.
 * @throws {Error} When `tar` fails or an entry lacks the `package/` root.
 */
function listTarballFiles(tarballPath) {
  const names = runTar(["-tzf", tarballPath]).toString("utf8").split("\n").filter((line) => line.length > 0);
  const files = [];
  for (const name of names) {
    if (name.endsWith("/")) {
      continue;
    }
    if (!name.startsWith(`${PACKAGE_ROOT_DIR}/`)) {
      throw new Error(`tarball entry outside "${PACKAGE_ROOT_DIR}/" root: ${name}`);
    }
    files.push(name.slice(PACKAGE_ROOT_DIR.length + 1));
  }
  return files;
}

/**
 * @brief Verifies the packed file set against the invariant, prefix allowlist, and required entries.
 * @details Each packed path MUST equal an invariant file or start with an allowed prefix (PKG-075).
 * Each required entry MUST be present (PKG-075). Complexity O(E * P) with P = allowlist size.
 * @param files {string[]} Relative packed file paths.
 * @return {void}
 * @side_effect Calls `recordFailure` per violation.
 */
function checkStructure(files) {
  const failuresBefore = failures.length;
  const fileSet = new Set(files);
  for (const file of files) {
    const allowed = INVARIANT_FILES.has(file) || ALLOWED_PREFIXES.some((prefix) => file.startsWith(prefix));
    if (!allowed) {
      recordFailure(`packed path outside publication allowlist (PKG-038, PKG-075): ${file}`);
    }
  }
  for (const required of REQUIRED_ENTRIES) {
    if (!fileSet.has(required)) {
      recordFailure(`required entry missing from tarball (PKG-075): ${required}`);
    }
  }
  if (failures.length === failuresBefore) {
    recordOk(`tarball structure: ${files.length} files, allowlist and required entries satisfied`);
  }
}

/**
 * @brief Collects every string leaf of a `bin`, `main`, or `exports` declaration.
 * @details Recurses through object values; non-string leaves are ignored. Pure; complexity O(n)
 * in declaration size.
 * @param value {unknown} Declaration value (string, object, array, or other).
 * @return {string[]} Declared target paths, still carrying any leading `./`.
 */
function collectStringTargets(value) {
  if (typeof value === "string") {
    return [value];
  }
  if (value !== null && typeof value === "object") {
    return Object.values(value).flatMap((nested) => collectStringTargets(nested));
  }
  return [];
}

/**
 * @brief Verifies the packed `package/package.json` identity and declared entry targets.
 * @details Compares packed `name` and `version` with the repository `package.json` (PKG-076).
 * Each `main`, `exports`, and `bin` target, normalized by stripping a leading `./`, MUST exist in
 * the tarball file set (PKG-076). Complexity O(T) with T = declared target count.
 * @param repoPackage {{ name: string, version: string, main?: unknown, exports?: unknown, bin?: unknown }}
 *        Repository `package.json` contents.
 * @param packedPackageJsonPath {string} Extracted `package/package.json` path.
 * @param files {string[]} Relative packed file paths.
 * @return {void}
 * @side_effect Calls `recordFailure` per violation.
 */
function checkIdentityAndTargets(repoPackage, packedPackageJsonPath, files) {
  const packed = JSON.parse(readFileSync(packedPackageJsonPath, "utf8"));
  if (packed.name !== repoPackage.name || packed.version !== repoPackage.version) {
    recordFailure(
      `packed identity mismatch (PKG-076): packed ${packed.name}@${packed.version}, repository ${repoPackage.name}@${repoPackage.version}`,
    );
  } else {
    recordOk(`packed identity ${packed.name}@${packed.version} matches repository package.json (PKG-076)`);
  }
  const fileSet = new Set(files);
  const targets = [
    ...collectStringTargets(repoPackage.main),
    ...collectStringTargets(repoPackage.exports),
    ...collectStringTargets(repoPackage.bin),
  ].map((target) => target.replace(/^\.\//, ""));
  for (const target of targets) {
    if (!fileSet.has(target)) {
      recordFailure(`declared target missing from tarball (PKG-076): ${target}`);
    }
  }
  recordOk(`${targets.length} declared bin/main/exports targets present in tarball (PKG-076)`);
}

/**
 * @brief Verifies that every skill path declared in the packed manifest exists in the tarball.
 * @details Reads `src/resources/skills/manifest.json` from the extraction. Skill `path` resolves
 * relative to the skills root; skill `debug` resolves relative to the skill directory, i.e.
 * the directory of `path` (REQ-152). Each resolved entry MUST exist in the tarball file set
 * (PKG-077). Complexity O(S).
 * @param packageDir {string} Extracted `package/` directory.
 * @param files {string[]} Relative packed file paths.
 * @return {void}
 * @side_effect Calls `recordFailure` per missing skill file.
 */
function checkSkillManifest(packageDir, files) {
  const skillsRoot = "src/resources/skills/";
  const manifest = JSON.parse(readFileSync(join(packageDir, skillsRoot, "manifest.json"), "utf8"));
  const fileSet = new Set(files);
  const skills = Array.isArray(manifest.skills) ? manifest.skills : [];
  for (const skill of skills) {
    if (typeof skill.path !== "string") {
      recordFailure("skill manifest entry without a string path (PKG-077)");
      continue;
    }
    const entries = [`${skillsRoot}${skill.path}`];
    if (typeof skill.debug === "string") {
      entries.push(`${skillsRoot}${posix.join(posix.dirname(skill.path), skill.debug)}`);
    }
    for (const entry of entries) {
      if (!fileSet.has(entry)) {
        recordFailure(`skill manifest entry missing from tarball (PKG-077): ${entry}`);
      }
    }
  }
  recordOk(`${skills.length} skill manifest entries resolve to packed files (PKG-077)`);
}

/**
 * @brief Lists every regular file below a directory as POSIX-relative paths.
 * @details Recursive, depth-first, lexical order from `readdirSync`. Complexity O(F).
 * @param root {string} Directory to scan.
 * @return {string[]} Paths relative to `root` with `/` separators.
 */
function listDirectoryFiles(root) {
  const found = [];
  const visit = (directory) => {
    for (const name of readdirSync(directory)) {
      const absolute = join(directory, name);
      if (statSync(absolute).isDirectory()) {
        visit(absolute);
      } else {
        found.push(relative(root, absolute).split("\\").join("/"));
      }
    }
  };
  visit(root);
  return found;
}

/**
 * @brief Verifies that the packed `dist/` tree and the repository `dist/` tree are byte-identical.
 * @details Forward pass: every packed `dist/` file MUST exist in the repository and match byte for
 * byte (PKG-078). Reverse pass: every repository `dist/` file except the release tarball itself MUST
 * be packed, so stale or unpacked outputs are reported (PKG-078). Complexity O(F) in packed bytes.
 * @param packageDir {string} Extracted `package/` directory.
 * @param files {string[]} Relative packed file paths.
 * @param tarballName {string} Tarball file name excluded from the reverse pass.
 * @return {void}
 * @side_effect Calls `recordFailure` per mismatch; reads repository and extracted files.
 */
function checkDistIdentity(packageDir, files, tarballName) {
  const packedDist = files.filter((file) => file.startsWith("dist/"));
  const repoDist = join(PROJECT_ROOT, "dist");
  for (const file of packedDist) {
    const repoFile = join(PROJECT_ROOT, file);
    if (!existsSync(repoFile)) {
      recordFailure(`packed dist file absent from repository dist/ (PKG-078): ${file}`);
      continue;
    }
    const packedBytes = readFileSync(join(packageDir, file));
    if (!packedBytes.equals(readFileSync(repoFile))) {
      recordFailure(`packed dist file differs from repository dist/ (PKG-078): ${file}`);
    }
  }
  for (const file of listDirectoryFiles(repoDist).map((name) => `dist/${name}`)) {
    if (file === `dist/${tarballName}`) {
      continue;
    }
    if (!packedDist.includes(file)) {
      recordFailure(`repository dist/ file not packed (stale or unpacked output, PKG-078): ${file}`);
    }
  }
  recordOk(`${packedDist.length} packed dist/ files byte-identical to repository dist/ (PKG-078)`);
}

/**
 * @brief Runs `node --check` on each named packed entry.
 * @details Syntax-only verification; executes nothing. Complexity O(E) child spawns.
 * @param packageDir {string} Extracted `package/` directory.
 * @param entries {string[]} Relative entries to check.
 * @return {void}
 * @side_effect Spawns one `node --check` child per entry; calls `recordFailure` on failure.
 */
function checkSyntax(packageDir, entries) {
  for (const entry of entries) {
    const result = spawnSync(process.execPath, ["--check", join(packageDir, entry)], { encoding: "utf8" });
    if (result.error || result.status !== 0) {
      recordFailure(`syntax check failed (PKG-079): ${entry} ${result.stderr ?? ""}`.trim());
    }
  }
  recordOk(`syntax verified for ${entries.join(", ")} (PKG-079)`);
}

/**
 * @brief Executes the repository `dist/cli.js --help` as an offline smoke run.
 * @details The repository `dist/` is byte-identical to the packed tree (checked by
 * `checkDistIdentity`), so this run exercises the shipped entry. Requires exit 0 and the
 * `mcp-google-api` name on stdout (PKG-079). Complexity O(1) plus child runtime bounded by timeout.
 * @return {void}
 * @side_effect Spawns one Node.js child process; calls `recordFailure` on failure.
 */
function checkCliSmoke() {
  const cliEntry = join(PROJECT_ROOT, "dist", "cli.js");
  const result = spawnSync(process.execPath, [cliEntry, "--help"], {
    encoding: "utf8",
    timeout: CLI_SMOKE_TIMEOUT_MS,
  });
  if (result.error) {
    recordFailure(`packaged CLI smoke run could not execute (PKG-079): ${result.error.message}`);
    return;
  }
  if (result.status !== 0 || !result.stdout.includes("mcp-google-api")) {
    recordFailure(
      `packaged CLI smoke run failed (PKG-079): exit ${result.status}, stderr: ${result.stderr.trim()}`,
    );
    return;
  }
  recordOk("packaged dist/cli.js --help exits 0 with mcp-google-api on stdout (PKG-079)");
}

/**
 * @brief Runs every artifact check in fixed order against the generated tarball.
 * @details Reads the repository `package.json`, derives the expected tarball name
 * `<name>-<version>.tgz`, verifies its presence, lists and structurally checks it, extracts it to a
 * private temp directory, and runs the identity, target, manifest, dist-identity, syntax, and smoke
 * checks. The temp directory is removed in `finally`. Complexity O(E + F).
 * @return {void}
 * @throws {Error} When the tarball is missing, unreadable, or its listing is structurally invalid.
 * @side_effect Creates and removes one temp directory under the OS temp root.
 */
function main() {
  const repoPackage = JSON.parse(readFileSync(join(PROJECT_ROOT, "package.json"), "utf8"));
  const tarballName = `${repoPackage.name}-${repoPackage.version}.tgz`;
  const tarballPath = join(PROJECT_ROOT, "dist", tarballName);
  if (!existsSync(tarballPath) || statSync(tarballPath).size === 0) {
    throw new Error(`release tarball missing or empty: dist/${tarballName}`);
  }
  const files = listTarballFiles(tarballPath);
  checkStructure(files);
  const extractRoot = mkdtempSync(join(tmpdir(), "check-release-artifacts-"));
  try {
    runTar(["-xzf", tarballPath, "-C", extractRoot]);
    const packageDir = join(extractRoot, PACKAGE_ROOT_DIR);
    checkIdentityAndTargets(repoPackage, join(packageDir, "package.json"), files);
    checkSkillManifest(packageDir, files);
    checkDistIdentity(packageDir, files, tarballName);
    checkSyntax(packageDir, SYNTAX_CHECKED_ENTRIES);
    checkCliSmoke();
  } finally {
    rmSync(extractRoot, { recursive: true, force: true });
  }
}

try {
  main();
} catch (error) {
  recordFailure(error instanceof Error ? error.message : String(error));
}

if (failures.length > 0) {
  for (const failure of failures) {
    console.error(`[check-release-artifacts] FAILED: ${failure}`);
  }
  process.exit(1);
}
console.log("[check-release-artifacts] all release artifact checks passed.");
